package mz.gov.mogovolas.expedientes.controller;
import mz.gov.mogovolas.expedientes.entity.*; import mz.gov.mogovolas.expedientes.repository.*; import mz.gov.mogovolas.expedientes.service.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.core.Authentication; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.web.bind.annotation.*;
@Controller public class WebController {final ExpedienteService es;final SectorRepository sr;final AuditoriaRepository ar;final UtilizadorRepository ur;final PapelRepository pr; public WebController(ExpedienteService e,SectorRepository s,AuditoriaRepository a,UtilizadorRepository u,PapelRepository p){es=e;sr=s;ar=a;ur=u;pr=p;} @GetMapping("/login")String login(){return"login";} @GetMapping("/")String home(Model m){m.addAttribute("indicadores",es.indicadores());return"index";} @GetMapping("/expedientes") @PreAuthorize("hasAuthority('EXPEDIENTE_VISUALIZAR')")String list(@RequestParam(required=false)String q,Model m){m.addAttribute("expedientes",es.listar(q));m.addAttribute("q",q);return"expedientes/lista";} @GetMapping("/expedientes/novo") @PreAuthorize("hasAuthority('EXPEDIENTE_CRIAR')")String novo(Model m){m.addAttribute("expediente",new Expediente());return"expedientes/form";} @PostMapping("/expedientes") @PreAuthorize("hasAuthority('EXPEDIENTE_CRIAR')")String criar(@ModelAttribute Expediente e,Authentication a){var x=es.criar(e,a.getName());return"redirect:/expedientes/"+x.getId();} @GetMapping("/expedientes/{id}") @PreAuthorize("hasAuthority('EXPEDIENTE_VISUALIZAR')")String detail(@PathVariable Long id,Model m){m.addAttribute("e",es.obter(id));m.addAttribute("sectores",sr.findAll());return"expedientes/detalhe";} @PostMapping("/expedientes/{id}/tramitar") @PreAuthorize("hasAuthority('EXPEDIENTE_TRAMITAR')")String tr(@PathVariable Long id,@RequestParam Long sectorDestino,@RequestParam(required=false)String observacao,Authentication a){es.tramitar(id,sectorDestino,observacao,a.getName());return"redirect:/expedientes/"+id;} @PostMapping("/expedientes/{id}/receber") @PreAuthorize("hasAuthority('EXPEDIENTE_RECEBER')")String rec(@PathVariable Long id,Authentication a){es.receber(id,a.getName());return"redirect:/expedientes/"+id;} @PostMapping("/expedientes/{id}/despacho") @PreAuthorize("hasAuthority('DESPACHO_EMITIR')")String dp(@PathVariable Long id,@RequestParam String texto,Authentication a){es.despacho(id,texto,a.getName());return"redirect:/expedientes/"+id;} @PostMapping("/expedientes/{id}/arquivar") @PreAuthorize("hasAuthority('EXPEDIENTE_ARQUIVAR')")String arq(@PathVariable Long id){es.arquivar(id);return"redirect:/expedientes/"+id;} @GetMapping("/administracao") @PreAuthorize("hasAuthority('UTILIZADOR_GERIR')")String admin(Model m){m.addAttribute("utilizadores",ur.findAll());m.addAttribute("papeis",pr.findAll());m.addAttribute("sectores",sr.findAll());return"admin";} @GetMapping("/auditoria") @PreAuthorize("hasAuthority('AUDITORIA_CONSULTAR')")String audit(Model m){m.addAttribute("auditorias",ar.findTop200ByOrderByDataHoraDesc());return"auditoria";} }
